function PageIntro({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) { return <div className="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-[10px] font-semibold uppercase tracking-[0.18em] text-[#1c5d9e]">{eyebrow}</p><h2 className="mt-2 text-2xl font-semibold tracking-tight text-slate-900">{title}</h2><p className="mt-2 max-w-2xl text-sm leading-relaxed text-slate-500">{description}</p></div>{action}</div>; }
function Metric({ label, value, note, icon: Icon, tone = "blue" }: { label: string; value: string; note: string; icon: React.ElementType; tone?: string }) { return <Card className="border-slate-200/80 bg-white shadow-[0_2px_10px_rgba(15,23,42,0.03)]"><CardContent className="p-4"><div className="flex items-start justify-between"><div><p className="text-xs font-medium text-slate-500">{label}</p><p className="mt-2 text-2xl font-semibold tracking-tight text-slate-900">{value}</p><p className="mt-1 text-[11px] text-slate-400">{note}</p></div><div className={cn("rounded-lg bg-slate-50 p-2", tone === "amber" ? "text-amber-600" : tone === "green" ? "text-emerald-600" : tone === "violet" ? "text-violet-600" : "text-[#1c5d9e]")}><Icon className="h-4 w-4" /></div></div></CardContent></Card>; }

function Dashboard() { const { data, refetch, isFetching } = trpc.dashboard.overview.useQuery(); return <><PageIntro eyebrow="Command center" title="Good morning, Maya" description="A unified view of what is trending, what needs a decision, and where margin is moving." action={<div className="flex gap-2"><Button variant="outline" size="sm" onClick={() => refetch()} disabled={isFetching}><RefreshCw className={cn("mr-2 h-3.5 w-3.5", isFetching && "animate-spin")} />Refresh</Button><Button size="sm" className="bg-[#1c5d9e] hover:bg-[#164b80]"><Plus className="mr-2 h-3.5 w-3.5" />New product brief</Button></div>} /><div className="mb-5 flex items-center gap-2 text-xs text-slate-400"><span className="h-2 w-2 rounded-full bg-emerald-500" />{data?.tenant.name ?? "Northstar Athletics"}<Badge variant="outline" className="border-amber-200 bg-amber-50 text-[10px] text-amber-700">{data?.tenant.demo ? "Demo data" : "Live data"}</Badge></div><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Active products" value={String(data?.metrics.activeProducts ?? 24)} note="Across 4 categories" icon={PackageCheck} /><Metric label="Needs your review" value={String(data?.metrics.needsReview ?? 7)} note="2 critical · 5 standard" icon={FileCheck2} tone="amber" /><Metric label="Signals this week" value={String(data?.metrics.weeklySignals ?? 148)} note="+18% vs last week" icon={Activity} tone="violet" /><Metric label="Readiness score" value={`${data?.metrics.readiness ?? 82}%`} note="Target: 85%" icon={CheckCircle2} tone="green" /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.5fr_0.9fr]"><Card className="border-slate-200/80 bg-white"><CardHeader className="flex flex-row items-center justify-between border-b border-slate-100 px-5 py-4"><div><CardTitle className="text-sm">Product pipeline</CardTitle><p className="mt-1 text-xs text-slate-400">Latest work across the active assortment.</p></div><Link href="/products" className="text-xs font-semibold text-[#1c5d9e]">View all <ArrowRight className="ml-1 inline h-3 w-3" /></Link></CardHeader><CardContent className="p-0">{data?.products.map((p) => <div key={p.id} className="grid gap-3 border-b border-slate-100 px-5 py-4 last:border-0 sm:grid-cols-[1.4fr_0.9fr_110px_100px] sm:items-center"><div><p className="text-xs font-semibold text-slate-800">{p.name}</p><p className="mt-1 text-[11px] text-slate-400">{p.category} · {p.ownerName}</p></div><Badge variant="outline" className="w-fit text-[10px]">{p.status.replace("_", " ")}</Badge><div><div className="mb-1 flex justify-between text-[10px] text-slate-400"><span>Progress</span><span>{p.completion}%</span></div><Progress value={p.completion} className="h-1.5" /></div><div className="text-[11px] font-semibold text-slate-600">{p.confidence}% confidence</div></div>)}</CardContent></Card><Card className="border-slate-200/80 bg-white"><CardHeader className="border-b border-slate-100 px-5 py-4"><CardTitle className="text-sm">Decision queue</CardTitle><p className="mt-1 text-xs text-slate-400">AI proposals waiting for a human decision.</p></CardHeader><CardContent className="p-0">{data?.reviewItems.map((item) => <Link href="/review" key={item.id} className="block border-b border-slate-100 px-5 py-4 last:border-0 hover:bg-slate-50"><div className="flex gap-3"><CircleAlert className={cn("mt-0.5 h-4 w-4", item.severity === "critical" ? "text-rose-500" : "text-amber-500")} /><div><p className="text-xs font-semibold text-slate-800">{item.title}</p><p className="mt-1 text-[11px] leading-relaxed text-slate-500">{item.reason}</p><p className="mt-2 text-[10px] text-slate-400">{item.confidence}% confidence · {item.severity}</p></div></div></Link>)}</CardContent></Card></div><div className="mt-6 grid gap-6 lg:grid-cols-3"><InsightCard icon={TrendingUp} title="Trend opportunity" tone="violet" metric="91 / 100" text="Sculpted utility is accelerating in women’s active with strong brand fit." link="/trends" /><InsightCard icon={RotateCcw} title="Returns signal" tone="amber" metric="$84.2k" text="Contour Knit Legging returns are concentrated around waistband compression." link="/returns" /><InsightCard icon={WalletCards} title="Margin opportunity" tone="green" metric="+4.8pp" text="Nearshore fabric scenario improves margin while reducing lead-time risk." link="/sourcing" /></div></>; }
function InsightCard({ icon: Icon, title, metric, text, link, tone }: { icon: React.ElementType; title: string; metric: string; text: string; link: string; tone: string }) { return <Link href={link}><Card className="h-full border-slate-200/80 bg-white transition-shadow hover:shadow-md"><CardContent className="p-5"><div className="flex items-center justify-between"><div className={cn("rounded-lg p-2", tone === "amber" ? "bg-amber-50 text-amber-600" : tone === "green" ? "bg-emerald-50 text-emerald-600" : "bg-violet-50 text-violet-600")}><Icon className="h-4 w-4" /></div><ArrowUpRight className="h-4 w-4 text-slate-300" /></div><p className="mt-5 text-xs font-semibold text-slate-600">{title}</p><p className="mt-2 text-2xl font-semibold tracking-tight text-slate-900">{metric}</p><p className="mt-2 text-xs leading-relaxed text-slate-500">{text}</p></CardContent></Card></Link>; }

function Trends() { return <><PageIntro eyebrow="Signal intelligence" title="Know what is next—and whether it belongs to you" description="Trend scores combine social momentum, search intent, competitor movement, sales history, brand fit, sourcing feasibility, and timing. Every score is inspectable." action={<Button className="bg-[#1c5d9e]"><Sparkles className="mr-2 h-4 w-4" />Run trend scan</Button>} /><div className="grid gap-3 sm:grid-cols-3"><Metric label="Signals monitored" value="1.2M" note="Across 10 signal families" icon={Activity} /><Metric label="High-confidence trends" value="38" note="+12 this week" icon={Target} tone="violet" /><Metric label="Commercial whitespace" value="14" note="Filtered by brand fit" icon={Globe2} tone="green" /></div><Card className="mt-6 border-slate-200/80 bg-white"><CardHeader className="flex flex-row items-center justify-between border-b border-slate-100 px-5 py-4"><div><CardTitle className="text-sm">Ranked opportunities</CardTitle><p className="mt-1 text-xs text-slate-400">Calibrated for Northstar Athletics · Spring 2027</p></div><Button variant="outline" size="sm"><Search className="mr-2 h-3.5 w-3.5" />Filter signals</Button></CardHeader><CardContent className="p-0">{trendRows.map((trend, index) => <div key={trend.name} className="grid gap-4 border-b border-slate-100 px-5 py-5 last:border-0 lg:grid-cols-[1.5fr_1fr_110px_130px_90px]"><div className="flex items-center gap-3"><div className={cn("h-9 w-9 rounded-xl", trend.color)} /><div><p className="text-xs font-semibold text-slate-800">{index + 1}. {trend.name}</p><p className="mt-1 text-[11px] text-slate-400">{trend.category}</p></div></div><div><p className="text-[10px] uppercase tracking-wide text-slate-400">Lifecycle</p><p className="mt-1 text-xs font-medium text-slate-700">{trend.stage}</p><p className="mt-1 text-[10px] text-slate-400">Action window: {trend.timing}</p></div><div><p className="text-[10px] uppercase tracking-wide text-slate-400">Composite</p><p className="mt-1 text-lg font-semibold text-slate-900">{trend.score}<span className="text-xs text-slate-400">/100</span></p></div><div><p className="text-[10px] uppercase tracking-wide text-slate-400">Brand fit</p><Badge variant="outline" className="mt-1 text-[10px]">{trend.fit}</Badge></div><Button variant="ghost" size="sm" className="self-center text-xs text-[#1c5d9e]">Inspect <ArrowRight className="ml-1 h-3 w-3" /></Button></div>)}</CardContent></Card></>; }

function Returns() { return <><PageIntro eyebrow="Returns intelligence" title="Turn returns into better products" description="Find the root cause behind returns, quantify margin impact, and feed approved learnings back into briefs, sizing, content, sourcing, and assortment decisions." action={<Button className="bg-[#1c5d9e]"><Plus className="mr-2 h-4 w-4" />Create action plan</Button>} /><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Return rate" value="8.6%" note="-1.2pp vs prior season" icon={RotateCcw} tone="green" /><Metric label="Avoidable impact" value="$146.7k" note="Across 4 active products" icon={TrendingDown} tone="amber" /><Metric label="Root causes found" value="19" note="7 need action" icon={CircleAlert} tone="violet" /><Metric label="Learning velocity" value="4.2 days" note="From signal to approved change" icon={Activity} /></div><Card className="mt-6 border-slate-200/80 bg-white"><CardHeader className="flex flex-row items-center justify-between border-b border-slate-100 px-5 py-4"><div><CardTitle className="text-sm">Return drivers and commercial impact</CardTitle><p className="mt-1 text-xs text-slate-400">Normalized across returns, exchanges, reviews, support, and product data.</p></div><Button variant="outline" size="sm"><BarChart3 className="mr-2 h-3.5 w-3.5" />View analytics</Button></CardHeader><CardContent className="p-0">{returnRows.map((item) => <div key={item.product} className="grid gap-4 border-b border-slate-100 px-5 py-5 last:border-0 lg:grid-cols-[1.4fr_110px_100px_1.2fr_100px_100px]"><div><p className="text-xs font-semibold text-slate-800">{item.product}</p><p className="mt-1 text-[11px] text-slate-400">Last 90 days · all channels</p></div><div><p className="text-[10px] uppercase tracking-wide text-slate-400">Rate</p><p className="mt-1 text-sm font-semibold text-slate-900">{item.rate}</p></div><div><p className="text-[10px] uppercase tracking-wide text-slate-400">Change</p><p className={cn("mt-1 text-xs font-semibold", item.delta.startsWith("+") ? "text-rose-600" : "text-emerald-600")}>{item.delta}</p></div><div><p className="text-[10px] uppercase tracking-wide text-slate-400">Leading driver</p><p className="mt-1 text-xs text-slate-700">{item.reason}</p></div><div><p className="text-[10px] uppercase tracking-wide text-slate-400">Impact</p><p className="mt-1 text-xs font-semibold text-slate-800">{item.impact}</p></div><Badge variant="outline" className={cn("h-fit w-fit text-[10px]", item.risk === "high" ? "border-rose-200 bg-rose-50 text-rose-700" : item.risk === "medium" ? "border-amber-200 bg-amber-50 text-amber-700" : "border-emerald-200 bg-emerald-50 text-emerald-700")}>{item.risk} risk</Badge></div>)}</CardContent></Card><div className="mt-6 grid gap-6 lg:grid-cols-2"><Card className="border-slate-200/80 bg-white"><CardHeader><CardTitle className="text-sm">Recommended interventions</CardTitle><p className="mt-1 text-xs text-slate-400">AI proposals are not applied automatically.</p></CardHeader><CardContent className="space-y-3">{["Re-test waistband compression and update size guidance", "Add color-accuracy photography to product content", "Review waterproofing claim against lab evidence"].map((item, i) => <div key={item} className="flex items-start gap-3 rounded-xl border border-slate-200 p-3"><div className="grid h-6 w-6 shrink-0 place-items-center rounded-full bg-amber-50 text-[10px] font-bold text-amber-700">{i + 1}</div><div className="flex-1"><p className="text-xs font-medium text-slate-700">{item}</p><p className="mt-1 text-[10px] text-slate-400">Proposed change · requires reviewer</p></div><Button variant="ghost" size="sm" className="text-[10px] text-[#1c5d9e]">Review</Button></div>)}</CardContent></Card><Card className="border-slate-200/80 bg-white"><CardHeader><CardTitle className="text-sm">Feedback coverage</CardTitle><p className="mt-1 text-xs text-slate-400">Source freshness and evidence quality.</p></CardHeader><CardContent className="space-y-4">{[["Returns events", "98%", "emerald"], ["Customer reviews", "84%", "sky"], ["Product attributes", "96%", "violet"], ["Supplier lot data", "61%", "amber"]].map(([label, value, tone]) => <div key={label}><div className="mb-1 flex justify-between text-xs"><span className="text-slate-600">{label}</span><span className="font-semibold text-slate-700">{value}</span></div><Progress value={Number(value.replace("%", ""))} className={cn("h-1.5", tone === "amber" && "[&>div]:bg-amber-500", tone === "violet" && "[&>div]:bg-violet-500")} /></div>)}</CardContent></Card></div></>; }

function Products() { return <><PageIntro eyebrow="Product pipeline" title="From brief to shelf, with every decision traceable" description="Manage structured briefs, concepts, variants, approvals, and readiness across seasons and categories." action={<Button className="bg-[#1c5d9e]"><Plus className="mr-2 h-4 w-4" />New product brief</Button>} /><div className="grid gap-3 sm:grid-cols-3"><Metric label="In development" value="18" note="6 need a decision" icon={PackageCheck} /><Metric label="Average readiness" value="78%" note="+9% this season" icon={CheckCircle2} tone="green" /><Metric label="At risk" value="4" note="2 linked to supplier data" icon={AlertTriangle} tone="amber" /></div><Card className="mt-6 border-slate-200/80 bg-white"><CardHeader><CardTitle className="text-sm">Active assortment</CardTitle><p className="mt-1 text-xs text-slate-400">Structured product records with evidence and approval state.</p></CardHeader><CardContent className="grid gap-3 sm:grid-cols-2">{["AeroFlex Recovery Hoodie", "Contour Knit Legging", "Terrain Run Shell", "Pulse Court Short", "Studio Rib Tank", "Axis Trail Sneaker"].map((name, i) => <div key={name} className="rounded-xl border border-slate-200 p-4"><div className="flex items-start justify-between"><div className="flex items-center gap-3"><div className="grid h-9 w-9 place-items-center rounded-lg bg-[#edf3fa] text-[#1c5d9e]"><PackageCheck className="h-4 w-4" /></div><div><p className="text-xs font-semibold text-slate-800">{name}</p><p className="mt-1 text-[11px] text-slate-400">{["Performance apparel", "Women’s active", "Outdoor", "Training"][i % 4]}</p></div></div><Badge variant="outline" className="text-[10px]">{["In review", "In development", "Blocked", "Approved"][i % 4]}</Badge></div><div className="mt-4 flex items-center gap-3"><Progress value={[86, 64, 48, 100, 72, 57][i]} className="h-1.5 flex-1" /><span className="text-[10px] font-semibold text-slate-600">{[86, 64, 48, 100, 72, 57][i]}%</span></div><p className="mt-3 text-[10px] text-slate-400">Owner: {i % 2 ? "Jordan Lee" : "Maya Chen"} · Updated {i + 1}h ago</p></div>)}</CardContent></Card></>; }

function Sourcing() { return <><PageIntro eyebrow="Sourcing intelligence" title="Protect margin before you commit" description="Compare supplier paths, landed costs, tariff scenarios, lead times, resilience, and sustainability with deterministic calculations." action={<Button className="bg-[#1c5d9e]"><Plus className="mr-2 h-4 w-4" />New scenario</Button>} /><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Target gross margin" value="64.8%" note="+4.8pp vs baseline" icon={WalletCards} tone="green" /><Metric label="Landed cost" value="$18.42" note="Per unit · balanced scenario" icon={Truck} /><Metric label="Lead-time risk" value="Moderate" note="2 suppliers flagged" icon={AlertTriangle} tone="amber" /><Metric label="Tariff exposure" value="$42.6k" note="At current duty assumptions" icon={Globe2} tone="violet" /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.2fr_0.8fr]"><Card className="border-slate-200/80 bg-white"><CardHeader><CardTitle className="text-sm">Scenario comparison</CardTitle><p className="mt-1 text-xs text-slate-400">AeroFlex Recovery Hoodie · 25,000 units · deterministic model</p></CardHeader><CardContent className="p-0"><div className="grid grid-cols-[1.4fr_1fr_1fr_1fr] border-y border-slate-100 bg-slate-50/60 px-5 py-3 text-[10px] font-semibold uppercase tracking-wide text-slate-400"><span>Scenario</span><span>Margin</span><span>Lead time</span><span>Risk</span></div>{[["Baseline offshore", "60.0%", "18 weeks", "High"], ["Balanced nearshore", "64.8%", "14 weeks", "Moderate"], ["Speed-first", "62.1%", "10 weeks", "Low"]].map(([name, margin, lead, risk], i) => <div key={name} className={cn("grid grid-cols-[1.4fr_1fr_1fr_1fr] items-center border-b border-slate-100 px-5 py-4 text-xs", i === 1 && "bg-emerald-50/40")}><span className="font-semibold text-slate-700">{name}{i === 1 && <Badge className="ml-2 bg-emerald-100 text-[9px] text-emerald-700 hover:bg-emerald-100">Recommended</Badge>}</span><span className="font-semibold text-slate-800">{margin}</span><span className="text-slate-500">{lead}</span><span className={cn("font-medium", risk === "High" ? "text-rose-600" : risk === "Moderate" ? "text-amber-600" : "text-emerald-600")}>{risk}</span></div>)}</CardContent></Card><Card className="border-slate-200/80 bg-white"><CardHeader><CardTitle className="text-sm">Calculation assumptions</CardTitle><p className="mt-1 text-xs text-slate-400">Every number is inspectable and versioned.</p></CardHeader><CardContent className="space-y-3">{[["Fabric and trims", "$6.84", "Supplier quote · 2d ago"], ["Cut and sew", "$4.10", "Factory capacity model"], ["Freight and duty", "$3.26", "Tariff table · v2026.09"], ["Packaging and handling", "$2.18", "Finance policy · v4"]].map(([a, b, c]) => <div key={a} className="flex items-center justify-between rounded-lg bg-slate-50 px-3 py-2.5"><div><p className="text-xs font-medium text-slate-700">{a}</p><p className="mt-0.5 text-[10px] text-slate-400">{c}</p></div><span className="text-xs font-semibold text-slate-800">{b}</span></div>)}<Button variant="outline" className="mt-2 w-full text-xs"><FileText className="mr-2 h-3.5 w-3.5" />Open assumptions ledger</Button></CardContent></Card></div></>; }

function Review() { const [done, setDone] = useState<number[]>([]); return <><PageIntro eyebrow="Human review" title="Make the call with the evidence in view" description="AI proposals stop here when confidence, validation, evidence, or business policy needs a human decision." action={<Button variant="outline"><Flag className="mr-2 h-3.5 w-3.5" />Review policy</Button>} /><div className="grid gap-3 sm:grid-cols-3"><Metric label="Waiting for review" value={String(7 - done.length)} note="Oldest item: 2h 14m" icon={FileCheck2} tone="amber" /><Metric label="High severity" value="2" note="SLA: 4 hours" icon={AlertTriangle} tone="amber" /><Metric label="Approved this week" value="31" note="94% without rework" icon={CheckCircle2} tone="green" /></div><div className="mt-6 space-y-3">{[{ id: 1, title: "Material composition conflicts with taxonomy", product: "AeroFlex Recovery Hoodie", confidence: "88%", severity: "High", reason: "The suggested blend does not match the allowed composition range for this category.", evidence: ["Supplier spec sheet", "Category rule: performance apparel", "AI extraction run #8F42"] }, { id: 2, title: "Waterproof rating inferred from incomplete evidence", product: "Terrain Run Shell", confidence: "71%", severity: "Critical", reason: "The product brief contains a water-resistant claim but no verified lab result or test date.", evidence: ["Product brief v3", "Missing: laboratory test result", "AI reasoning run #A1D9"] }, { id: 3, title: "Suggested size curve needs merchant confirmation", product: "Contour Knit Legging", confidence: "93%", severity: "Medium", reason: "The proposed curve is based on historical sell-through but may under-serve the current target segment.", evidence: ["Size curve policy v2", "Last season sell-through", "Segment: women’s active"] }].map((item) => <Card key={item.id} className={cn("border-slate-200/80 bg-white", done.includes(item.id) && "opacity-60")}><CardContent className="p-5"><div className="flex flex-col gap-4 lg:flex-row lg:items-start"><div className={cn("rounded-lg p-2", item.severity === "Critical" ? "bg-rose-50 text-rose-600" : item.severity === "High" ? "bg-amber-50 text-amber-600" : "bg-slate-100 text-slate-500")}><CircleAlert className="h-5 w-5" /></div><div className="flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className="text-sm font-semibold text-slate-800">{item.title}</h3><Badge variant="outline" className="text-[10px]">{item.severity}</Badge></div><p className="mt-1 text-xs text-slate-400">{item.product} · {item.confidence} confidence · Proposal is not yet authoritative</p><p className="mt-4 text-xs leading-relaxed text-slate-600">{item.reason}</p><div className="mt-4 flex flex-wrap gap-2">{item.evidence.map((e) => <span key={e} className="rounded-md bg-slate-50 px-2 py-1 text-[10px] text-slate-500"><FileCheck2 className="mr-1 inline h-3 w-3" />{e}</span>)}</div></div><div className="flex shrink-0 gap-2"><Button size="sm" className="bg-emerald-600 hover:bg-emerald-700" disabled={done.includes(item.id)} onClick={() => setDone([...done, item.id])}><Check className="mr-1.5 h-3.5 w-3.5" />Approve</Button><Button size="sm" variant="outline" disabled={done.includes(item.id)}>Changes</Button><Button size="sm" variant="ghost" disabled={done.includes(item.id)}>Reject</Button></div></div></CardContent></Card>)}</div></>; }

function Concepts() { return <><PageIntro eyebrow="Innovation copilot" title="Explore concepts without losing control" description="Generate structured, evidence-linked product concepts, compare trade-offs, and send only reviewed proposals into the product pipeline." action={<Button className="bg-[#1c5d9e]"><Sparkles className="mr-2 h-4 w-4" />Create concept</Button>} /><div className="grid gap-6 lg:grid-cols-[1fr_1fr]"><Card className="border-slate-200/80 bg-white"><CardHeader><CardTitle className="text-sm">Concept brief</CardTitle><p className="mt-1 text-xs text-slate-400">A structured brief is safer than a blank prompt.</p></CardHeader><CardContent className="space-y-4"><div className="rounded-xl bg-[#f5f7fa] p-4"><p className="text-[10px] font-semibold uppercase tracking-wide text-slate-400">Opportunity</p><p className="mt-2 text-sm leading-relaxed text-slate-700">Build a transitional active layer for urban commuters that feels polished enough for work and performs during movement.</p></div>{[["Target customer", "Urban active professional"], ["Price architecture", "$128–$168 retail"], ["Brand constraint", "Low-logo, tactile, adaptable"], ["Evidence", "Sculpted utility trend · 91/100"]].map(([a, b]) => <div key={a} className="flex items-center justify-between border-b border-slate-100 pb-3 text-xs"><span className="text-slate-400">{a}</span><span className="font-medium text-slate-700">{b}</span></div>)}<Button className="w-full bg-[#1c5d9e]"><Bot className="mr-2 h-4 w-4" />Generate 3 concept directions</Button></CardContent></Card><Card className="border-slate-200/80 bg-white"><CardHeader><CardTitle className="text-sm">Recent concept directions</CardTitle><p className="mt-1 text-xs text-slate-400">All outputs are proposals with provenance.</p></CardHeader><CardContent className="space-y-3">{[["Transit Shell", "Strongest commercial fit", "88%"], ["Soft Utility Blazer", "Highest brand distinctiveness", "84%"], ["Modular Layer Vest", "Best margin potential", "81%"]].map(([a, b, c], i) => <div key={a} className="rounded-xl border border-slate-200 p-4"><div className="flex items-center justify-between"><div className="flex items-center gap-3"><div className="grid h-9 w-9 place-items-center rounded-lg bg-violet-50 text-violet-600"><Palette className="h-4 w-4" /></div><div><p className="text-xs font-semibold text-slate-800">{a}</p><p className="mt-1 text-[11px] text-slate-400">{b}</p></div></div><span className="text-xs font-semibold text-slate-700">{c}</span></div><div className="mt-3 flex gap-2"><Badge variant="outline" className="text-[9px]">Trend evidence</Badge><Badge variant="outline" className="text-[9px]">Margin checked</Badge><Badge variant="outline" className="text-[9px]">Needs review</Badge></div></div>)}</CardContent></Card></div></>; }

function LinePlan() { const cells = ["Transit Shell", "Contour Legging", "Soft Utility Blazer", "Studio Rib Tank", "Axis Trail Sneaker", "Pulse Court Short"]; return <><PageIntro eyebrow="Visual line planning" title="Balance the line before you buy the line" description="A shared planning canvas for assortment cohesion, coverage, price architecture, margin, trend exposure, and channel fit." action={<Button className="bg-[#1c5d9e]"><Plus className="mr-2 h-4 w-4" />Add concept</Button>} /><div className="mb-5 flex flex-wrap gap-2"><Badge className="bg-[#1c5d9e] hover:bg-[#1c5d9e]">Spring 2027</Badge><Badge variant="outline">Women’s active</Badge><Badge variant="outline">Balanced scenario</Badge><Button variant="outline" size="sm" className="ml-auto"><Settings2 className="mr-2 h-3.5 w-3.5" />Scenario settings</Button></div><div className="grid gap-6 xl:grid-cols-[1fr_300px]"><Card className="overflow-hidden border-slate-200/80 bg-white"><CardContent className="overflow-x-auto p-0"><div className="min-w-[720px]"><div className="grid grid-cols-4 border-b border-slate-100 bg-slate-50/60 px-5 py-3 text-[10px] font-semibold uppercase tracking-wide text-slate-400"><span>Assortment concept</span><span>Price tier</span><span>Margin</span><span>Coverage</span></div>{cells.map((name, i) => <div key={name} className="grid grid-cols-4 items-center border-b border-slate-100 px-5 py-4 last:border-0"><div className="flex items-center gap-3"><div className={cn("h-10 w-10 rounded-lg", ["bg-slate-900", "bg-stone-300", "bg-slate-500", "bg-rose-200", "bg-amber-700", "bg-indigo-400"][i])} /><div><p className="text-xs font-semibold text-slate-800">{name}</p><p className="mt-1 text-[10px] text-slate-400">{["Core hero", "Core volume", "Premium", "Entry", "Halo", "Core volume"][i]}</p></div></div><span className="text-xs text-slate-600">{["$148", "$98", "$168", "$58", "$178", "$68"][i]}</span><span className="text-xs font-semibold text-emerald-600">{["66.2%", "68.4%", "61.9%", "72.1%", "58.4%", "70.2%"][i]}</span><div className="pr-8"><Progress value={[87, 72, 54, 68, 46, 74][i]} className="h-1.5" /></div></div>)}</div></CardContent></Card><Card className="border-slate-200/80 bg-white"><CardHeader><CardTitle className="text-sm">Plan health</CardTitle><p className="mt-1 text-xs text-slate-400">Balanced scenario · live calculations</p></CardHeader><CardContent className="space-y-4">{[["Trend exposure", "Healthy", "text-emerald-600"], ["Price coverage", "Healthy", "text-emerald-600"], ["Margin risk", "Watch", "text-amber-600"], ["Category gap", "1 gap", "text-rose-600"]].map(([a, b, c]) => <div key={a} className="flex items-center justify-between border-b border-slate-100 pb-3"><span className="text-xs text-slate-500">{a}</span><span className={cn("text-xs font-semibold", c)}>{b}</span></div>)}<Button variant="outline" className="w-full text-xs"><BarChart3 className="mr-2 h-3.5 w-3.5" />Open scenario compare</Button></CardContent></Card></div></>; }

function Integrations() { return <><PageIntro eyebrow="Connected stack" title="Make every system part of the workflow" description="Connect commerce, PLM, ERP, design, returns, analytics, sourcing, model providers, and event transport through explicit adapters." action={<Button className="bg-[#1c5d9e]"><Plus className="mr-2 h-4 w-4" />Add integration</Button>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{[["Commerce", "Shopify", "Connected", "Product catalog · Orders · Inventory", "emerald"], ["Design", "SVG artboard demo", "Connected", "Vector preview · Spec export", "emerald"], ["PLM", "Generic REST adapter", "Needs attention", "Product sync · Attribute mapping", "amber"], ["Returns", "Loop / custom API", "Demo", "Return reasons · Exchanges", "sky"], ["AI routing", "Safe structured policy", "Connected", "Schema validation · Review intercept", "emerald"], ["ERP", "Not configured", "Unavailable", "Margin sync · Inventory handoff", "slate"]].map(([kind, provider, state, caps, tone]) => <Card key={kind} className="border-slate-200/80 bg-white"><CardContent className="p-5"><div className="flex items-start justify-between"><div className="flex items-center gap-3"><div className="grid h-9 w-9 place-items-center rounded-lg bg-slate-50 text-slate-600"><CloudCog className="h-4 w-4" /></div><div><p className="text-xs font-semibold text-slate-800">{kind}</p><p className="mt-1 text-[11px] text-slate-400">{provider}</p></div></div><span className={cn("h-2 w-2 rounded-full", tone === "emerald" ? "bg-emerald-500" : tone === "amber" ? "bg-amber-500" : tone === "sky" ? "bg-sky-500" : "bg-slate-300")} /></div><p className="mt-4 text-[11px] text-slate-500">{caps}</p><div className="mt-4 flex items-center justify-between"><span className="text-[10px] font-medium text-slate-500">{state}</span><Button variant="ghost" size="sm" className="text-[10px] text-[#1c5d9e]">Configure <ArrowRight className="ml-1 h-3 w-3" /></Button></div></CardContent></Card>)}</div></>; }

function Team() { return <><PageIntro eyebrow="Governance" title="Make access match responsibility" description="Manage memberships, role scopes, support access, and auditability across your workspace." action={<Button className="bg-[#1c5d9e]"><Plus className="mr-2 h-4 w-4" />Invite member</Button>} /><Card className="border-slate-200/80 bg-white"><CardHeader><CardTitle className="text-sm">Workspace members</CardTitle><p className="mt-1 text-xs text-slate-400">Northstar Athletics · 9 demo roles available</p></CardHeader><CardContent className="p-0">{roles.map((item, i) => <div key={item} className="flex flex-col gap-3 border-b border-slate-100 px-5 py-4 last:border-0 sm:flex-row sm:items-center"><div className="grid h-8 w-8 place-items-center rounded-full bg-[#edf3fa] text-[10px] font-bold text-[#1c5d9e]">{item.split(" ").map((x) => x[0]).join("").slice(0, 2)}</div><div className="min-w-0 flex-1"><p className="text-xs font-semibold text-slate-800">{item}</p><p className="mt-1 text-[11px] text-slate-400">{item.toLowerCase().replaceAll(" ", ".")}@demo.retailforge.local</p></div><div className="flex flex-wrap gap-1">{rolePermissions[item].slice(0, 2).map((permission) => <Badge key={permission} variant="outline" className="text-[9px]">{permission}</Badge>)}</div><Badge variant="outline" className="w-fit border-emerald-200 bg-emerald-50 text-[10px] text-emerald-700">Active</Badge><Button variant="ghost" size="sm" className="text-xs">Manage</Button></div>)}</CardContent></Card></>; }

function Health() { return <><PageIntro eyebrow="Operations" title="Know when the system needs you" description="Health, freshness, jobs, provider status, and event delivery in one operator view." action={<Button variant="outline"><RefreshCw className="mr-2 h-3.5 w-3.5" />Run checks</Button>} /><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Platform health" value="99.98%" note="Last 30 days" icon={Gauge} tone="green" /><Metric label="Active jobs" value="12" note="0 failed · 2 waiting review" icon={Activity} /><Metric label="AI cache hit rate" value="43%" note="Last 24 hours" icon={Bot} tone="violet" /><Metric label="Data freshness" value="96%" note="Across connected sources" icon={RefreshCw} tone="green" /></div><div className="mt-6 grid gap-6 lg:grid-cols-2">{[["Database and tenant policies", "Operational", "All tenant-scoped checks passing", "emerald"], ["AI provider routing", "Operational", "Structured output validation healthy", "emerald"], ["PLM adapter", "Attention", "Credential expires in 6 days", "amber"], ["Returns ingestion", "Demo mode", "Connect a provider to enable live events", "sky"]].map(([a, b, c, tone]) => <Card key={a} className="border-slate-200/80 bg-white"><CardContent className="flex items-center gap-4 p-5"><div className={cn("grid h-10 w-10 place-items-center rounded-xl", tone === "emerald" ? "bg-emerald-50 text-emerald-600" : tone === "amber" ? "bg-amber-50 text-amber-600" : "bg-sky-50 text-sky-600")}><CheckCircle2 className="h-5 w-5" /></div><div className="flex-1"><div className="flex items-center justify-between gap-3"><p className="text-xs font-semibold text-slate-800">{a}</p><span className="text-[10px] font-semibold text-slate-500">{b}</span></div><p className="mt-1 text-[11px] text-slate-400">{c}</p></div></CardContent></Card>)}</div></>; }

const sampleProductsCsv = `sku,product_name,category,season,channel,region,unit_cost,retail_price,units_sold,units_returned,inventory_on_hand,return_rate,top_return_reason\nRF-1001,Contour Knit Legging,Women's Active,Spring 2027,DTC,US,22.40,98.00,18420,3390,4820,0.184,Waistband compression\nRF-1002,AeroFlex Recovery Hoodie,Performance Apparel,Spring 2027,DTC,US,31.60,128.00,12100,1428,3100,0.118,Color differs from photos\nRF-1003,Terrain Run Shell,Outdoor,Spring 2027,Wholesale,US,48.20,178.00,8200,795,1920,0.097,Waterproofing expectation\nRF-1004,Pulse Court Short,Training,Spring 2027,DTC,US,15.10,68.00,15100,634,6400,0.042,Size exchange\nRF-1005,Studio Rib Tank,Women's Active,Spring 2027,DTC,EU,12.80,58.00,9800,510,3600,0.052,Fit preference\nRF-1006,Axis Trail Sneaker,Footwear,Spring 2027,DTC,US,54.00,178.00,6400,448,1100,0.070,Heel fit`;
